df <- read.csv("review-survey.csv", stringsAsFactors = FALSE, check.names = FALSE, na.strings = c('', 'NA', 'null', 'NULL'))
work <- na.omit(data.frame(tc=as.numeric(df$too_cheap), ch=as.numeric(df$cheap), ex=as.numeric(df$expensive), te=as.numeric(df$too_expensive)))
prices <- sort(unique(as.numeric(as.matrix(work))))
n <- nrow(work)
cdf_ge <- function(x) sapply(prices, function(p) mean(x >= p))
cdf_le <- function(x) sapply(prices, function(p) mean(x <= p))
pmc <- cdf_ge(work$tc); cheap <- cdf_ge(work$ch); expc <- cdf_le(work$ex); tooe <- cdf_le(work$te)
cross <- function(a, b) {
  d <- a - b
  for (i in 2:length(d)) {
    if (d[i-1] == 0) return(prices[i-1])
    if (d[i-1] * d[i] < 0) return(prices[i])
  }
  NA_real_
}
cat(sprintf('n=%.16g\n', n))
cat(sprintf('ipp=%.16g\n', cross(expc, cheap)))
cat(sprintf('opp=%.16g\n', cross(tooe, pmc)))

